<?php
require __DIR__.'/core.php';require __DIR__.'/profile-core.php';require __DIR__.'/services-core.php';require __DIR__.'/quotes-core.php';require __DIR__.'/bookings-core.php';
$_SERVER['SCRIPT_NAME']=preg_replace('~/account/requests.php$~','/account/index.php',$_SERVER['SCRIPT_NAME']);
$b=null;$r=null;$rows=[];$e=null;$error='';$notice='';$filter=(string)($_GET['status']??'');$page=max(1,min(100000,(int)($_GET['page']??1)));
try{
 start();$u=user();$b=business();if(!$b)go('business');$notice=(string)($_SESSION['request_notice']??'');unset($_SESSION['request_notice']);
 $prefix='/rest/v1/business_booking_requests?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.profile_env();$id=(string)($_GET['id']??$_POST['id']??'');
 if($id!==''){if(!preg_match('/\A[0-9a-f-]{36}\z/',$id))throw new RuntimeException('Request unavailable.');$found=api($prefix.'&id=eq.'.rawurlencode($id).'&select=*',[],'GET',$_SESSION['auth']['access_token']);$r=$found[0]??null;if(!$r)throw new RuntimeException('Request unavailable.');$found=api('/rest/v1/business_enquiries?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.profile_env().'&id=eq.'.rawurlencode($id).'&select=*',[],'GET',$_SESSION['auth']['access_token']);$e=$found[0]??null;if(!$e)throw new RuntimeException('Request unavailable.');}
 if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();if(!$r)throw new RuntimeException('Request unavailable.');$action=(string)($_POST['action']??'');if(!in_array($action,['quote','accept','decline','convert'],true))throw new RuntimeException('Choose a request action.');
 if(in_array($action,['accept','convert'],true)&&($_POST['confirm']??'')!=='on')throw new RuntimeException('Confirm you have reviewed the price, schedule and capacity with the customer.');
 $saved=profile_rpc('business_booking_request_action',['p_business'=>$b['id'],'p_environment'=>profile_env(),'p_id'=>$id,'p_version'=>(int)($_POST['version']??0),'p_action'=>$action]);
 if(isset($saved['quote_id'])){header('Location: quotes.php?id='.rawurlencode($saved['quote_id']),true,303);exit;}if(isset($saved['booking_id'])){header('Location: bookings.php?id='.rawurlencode($saved['booking_id']),true,303);exit;}
 $_SESSION['request_notice']='Request '.($action==='accept'?'accepted':'declined').'. No notification sent.';header('Location: requests.php?id='.rawurlencode($id),true,303);exit;
 }
 if(!$r){if(!in_array($filter,['','Pending','Accepted','Declined','Booked'],true))throw new RuntimeException('Choose a valid status.');$rows=api($prefix.($filter?'&status=eq.'.rawurlencode($filter):'').'&select=*&order=created_at.desc,id.desc&limit=21&offset='.(($page-1)*20),[],'GET',$_SESSION['auth']['access_token']);}
}catch(AccountSessionExpired $ex){$_SESSION=['csrf'=>bin2hex(random_bytes(32)),'notice'=>$ex->getMessage()];session_regenerate_id(true);go('signin');}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Requests unavailable. Please try again.';}
function request_schedule(array $r): string{return (new DateTimeImmutable($r['preferred_at']))->setTimezone(new DateTimeZone($r['time_zone']))->format('j M Y · H:i').' · '.$r['time_zone'];}
