<?php if($r&&$e):?><a href="requests.php">← All requests</a><article class="panel"><div class="service-title"><h2><?=esc($e['customer_name'])?></h2><span class="badge"><?=esc($r['status']==='Pending'?'Pending confirmation':$r['status'])?></span></div><p><?=esc($e['email'])?> <?=esc($e['phone'])?></p><h3><?=esc($r['service']['name'])?></h3><p><?=esc($r['service']['mode']==='quote'?'Quote required':services_price($r['service'],$r['currency']))?> · <?=(int)$r['service']['duration']?> minutes</p><p class="description"><?=nl2br(esc($r['address']))?></p><p>Preferred: <?=esc(request_schedule($r))?></p><p class="description"><?=nl2br(esc($e['requirements']))?></p><p class="muted">Service, price, currency and time zone are saved as requested. Check capacity and agree any changes with the customer. No notification is sent.</p>
<?php if($r['quote_id']):?><p><a href="quotes.php?id=<?=esc($r['quote_id'])?>">Open quote</a> · Customer acceptance is required before accepting this quoted request.</p><?php endif;if($r['booking_id']):?><p><a class="button" href="bookings.php?id=<?=esc($r['booking_id'])?>">Open booking</a></p><?php endif;?>
<?php if(in_array($r['status'],['Pending','Accepted'],true)):form_start();?><input type="hidden" name="id" value="<?=esc($r['id'])?>"><input type="hidden" name="version" value="<?=(int)$r['version']?>">
<?php if($r['status']==='Pending'):?><button class="button secondary" name="action" value="quote">Create / open quote</button><button class="button secondary" name="action" value="decline">Decline request</button><?php endif;?>
<label class="check"><input type="checkbox" name="confirm"> I have reviewed the price, preferred schedule and capacity with the customer.</label><button class="button" name="action" value="<?=$r['status']==='Pending'?'accept':'convert'?>"><?=$r['status']==='Pending'?'Accept request':'Create / open booking'?></button></form><?php endif;?></article>
<?php elseif(!$error):?><form method="get" class="enquiry-filter"><label for="status">Status</label><select name="status" id="status"><option value="">All requests</option><?php foreach(['Pending','Accepted','Declined','Booked'] as $s):?><option value="<?=$s?>" <?=$filter===$s?'selected':''?>><?=$s==='Pending'?'Pending confirmation':$s?></option><?php endforeach;?></select><button class="button secondary">Filter</button></form><section class="panel"><?php foreach(array_slice($rows,0,20) as $row):?><article class="service-card"><div class="service-title"><h2><a href="requests.php?id=<?=esc($row['id'])?>"><?=esc($row['service']['name'])?> · <?=esc(strtoupper(substr($row['id'],0,8)))?></a></h2><span class="badge"><?=esc($row['status']==='Pending'?'Pending confirmation':$row['status'])?></span></div><p><?=esc(request_schedule($row))?></p><p><?=esc($row['service']['mode']==='quote'?'Quote required':services_price($row['service'],$row['currency']))?></p></article><?php endforeach;if(!$rows):?><h2>No requests<?=$filter?' with this status':' yet'?></h2><p>Customers can request a booking from your published business page.</p><?php endif;?></section><nav class="enquiry-pagination" aria-label="Request pages"><?php if($page>1):?><a href="?page=<?=$page-1?>&amp;status=<?=esc($filter)?>">Previous</a><?php endif;if(count($rows)>20):?><a href="?page=<?=$page+1?>&amp;status=<?=esc($filter)?>">Next</a><?php endif;?></nav><?php endif;endif;?></main><footer>© <?=date('Y')?> FaraiOS</footer></body></html>
